"""
strategies/base_strategy.py
---------------------------
Base class and data contracts for algorithmic trading strategies.
"""

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from datetime import datetime
from typing import Dict, List, Optional, Any
import pandas as pd


@dataclass
class TradeSignal:
    """Standardized trade signal generated by an algorithmic strategy."""
    asset: str
    symbol: str
    direction: str  # "BUY" or "SELL"
    strategy_name: str
    timeframe: str
    entry_price: float
    stop_loss: float
    take_profit_1: float
    take_profit_2: float
    risk_reward_ratio: float
    recommended_lot_size: float
    dollar_risk: float
    account_equity: float
    confluences: List[str]
    bar_time: datetime
    metadata: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "asset": self.asset,
            "symbol": self.symbol,
            "direction": self.direction,
            "strategy_name": self.strategy_name,
            "timeframe": self.timeframe,
            "entry_price": self.entry_price,
            "stop_loss": self.stop_loss,
            "take_profit_1": self.take_profit_1,
            "take_profit_2": self.take_profit_2,
            "risk_reward_ratio": self.risk_reward_ratio,
            "recommended_lot_size": self.recommended_lot_size,
            "dollar_risk": self.dollar_risk,
            "account_equity": self.account_equity,
            "confluences": self.confluences,
            "bar_time": self.bar_time.isoformat() if hasattr(self.bar_time, "isoformat") else str(self.bar_time),
            "metadata": self.metadata
        }


class BaseStrategy(ABC):
    """Abstract interface that all instrument-specific strategies implement."""

    def __init__(self, name: str, asset: str):
        self.name = name
        self.asset = asset
        self.last_status: str = "Initialized"

    @abstractmethod
    def evaluate(
        self,
        symbol: str,
        data_frames: Dict[str, pd.DataFrame],
        live_tick: dict,
        symbol_specs: dict,
        account_equity: float
    ) -> Optional[TradeSignal]:
        """
        Evaluates real-time market data across timeframes (M5, M15, H1, H4)
        and generates a TradeSignal if all gatekeepers and setup conditions are met.
        """
        pass
